package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class SessionInvalidationPhase8AContractTest{
	@Test void adminRevocationIsExactTenantSessionAuditedBeforeCommitAndPublishedAfterCommit()throws Exception{String s=Files.readString(Path.of("..","shale-server","src","main","java","com","shale","server","runtime","SessionManagementService.java"));String mutate=method(s,"private List<UUID> mutate");assertTrue(mutate.contains("WHERE ShaleClientId=?"));assertTrue(mutate.contains("AND SessionId=?"));assertTrue(mutate.indexOf("appendAudit(c,actor")<mutate.indexOf("c.commit()"),"security audit must be in the mutation transaction");String admin=method(s,"public void revokeTenantSessionAsAdmin");assertTrue(admin.contains("publishAfterCommit(actor,mutate("),"publication must only receive the committed mutation result");}
	@Test void disableRemovalAndCredentialResetRevokeDurableSessionsInTheirTransactions()throws Exception{String s=Files.readString(Path.of("src/main/java/com/shale/data/dao/UserDao.java"));assertTrue(count(s,"revokeAllSessions(con,")>=4);assertTrue(s.contains("RevocationReason='SECURITY'"));assertTrue(s.contains("AND RevokedAt IS NULL"));}
	@Test void boundValidationAlsoRequiresCurrentAccountEligibility()throws Exception{String s=Files.readString(Path.of("src/main/java/com/shale/data/dao/UserSessionDao.java"));assertTrue(s.contains("JOIN dbo.Users u"));assertTrue(s.contains("COALESCE(u.is_deleted,0)=0"));assertTrue(s.contains("COALESCE(u.IsRemoved,0)=0"));}
	private static int count(String s,String x){int n=0,p=0;while((p=s.indexOf(x,p))>=0){n++;p+=x.length();}return n;}
	private static String method(String source,String signature){int start=source.indexOf(signature);if(start<0)throw new AssertionError("Missing method: "+signature);int open=source.indexOf('{',start),depth=0;for(int i=open;i<source.length();i++){char value=source.charAt(i);if(value=='{')depth++;if(value=='}'&&--depth==0)return source.substring(start,i+1);}throw new AssertionError("Unclosed method: "+signature);}
}
